#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <sys/types.h>

void save_secrete_file(const char *directory, const char *filename, const char *content) {
    char path[1024];
    snprintf(path, sizeof(path), "%s/%s", directory, filename);

    // Check if directory exists and is writable
    struct stat st;
    if (stat(directory, &st) != 0 || !(st.st_mode & S_IWUSR)) {
        fprintf(stderr, "Directory not writable or does not exist: %s\n", directory);
        return;
    }

    FILE *file = fopen(path, "w");
    if (file == NULL) {
        perror("Failed to open file");
        return;
    }

    fprintf(file, "%s", content);
    fclose(file);

    // Set file permissions to restrict access to owner only
    if (chmod(path, S_IRUSR | S_IWUSR) != 0) {
        perror("Failed to set file permissions");
        return;
    }

    // Set file owner to current user (only possible if process has sufficient privileges)
    if (chown(path, getuid(), -1) != 0) {
        perror("Failed to set file owner");
        return;
    }

    printf("Secret file saved securely: %s\n", path);
}
